#[derive(Clone, Debug)]
pub struct RegistryConfig {
    pub kind: Ecosystem,
    pub url: Option<String>,
    /// Upload endpoint of a `pypi` registry whose index (`url`) is not also where files are uploaded.
    pub publish_url: Option<String>,
}

/// One declared release artifact. `target` is opaque -- Callisto passes it to
/// whatever builds the bytes and never parses it -- and `asset_name` is the
/// externally stable name the artifact is published under.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProductArtifactConfig {
    /// The package whose build produces these bytes. Need not be the product.
    pub package: PackageId,
    pub target: String,
    pub asset_name: String,
}

/// Both `product-package` and every `[[release.artifact]] package` must name one
/// ecosystem-qualified identity; one parser so the two cannot drift.
fn parse_qualified_package(value: &str, key: &str) -> Result<PackageId, ConfigError> {
    let package = PackageId::parse(value).map_err(|_error| ConfigError::InvalidProductRelease {
        detail: format!("{key} must be an ecosystem-qualified package identity"),
    })?;
    if package.ecosystem().is_none() {
        return Err(ConfigError::InvalidProductRelease {
            detail: format!("{key} must be an ecosystem-qualified package identity"),
        });
    }
    Ok(package)
}

fn resolve_product_release(raw: RawProductReleaseConfig) -> Result<ProductReleaseConfig, ConfigError> {
    let package = parse_qualified_package(&raw.product_package, "product-package")?;
    if raw.artifact.is_empty() {
        return Err(ConfigError::InvalidProductRelease {
            detail: "a [release] section must declare at least one [[release.artifact]]".to_owned(),
        });
    }
    let mut artifacts = Vec::with_capacity(raw.artifact.len());
    let mut seen_assets = BTreeSet::new();
    for entry in &raw.artifact {
        let package = parse_qualified_package(&entry.package, "[[release.artifact]] package")?;
        if !is_safe_artifact_component(&entry.target) || !is_safe_artifact_component(&entry.asset_name) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!(
                    "artifact target `{}` and asset-name `{}` must each be a single safe path component",
                    entry.target, entry.asset_name
                ),
            });
        }
        if !seen_assets.insert(entry.asset_name.clone()) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!("asset-name `{}` is declared more than once", entry.asset_name),
            });
        }
        artifacts.push(ProductArtifactConfig {
            package,
            target: entry.target.clone(),
            asset_name: entry.asset_name.clone(),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("release-trigger = {other}"),
        }),
    }
}

/// A `[[package]]` rule applies to `id` when the names match and, for a
/// Prefixed rule, `id`'s package actually has a manifest in that ecosystem.
///
/// `PackageId::matches` alone is not enough here: it treats a Bare id as an
/// ecosystem wildcard, so a Prefixed rule for one ecosystem (`pypi:foo`)
/// would otherwise match a same-named package that only exists in another
/// (a Cargo-only `foo`) -- `package_ecosystems` is the package's real,
/// manifest-derived ecosystem set, independent of whether its `PackageId`
/// happens to be Bare (unpromoted) or Prefixed.
pub(crate) fn rule_applies(rule_id: &PackageId, id: &PackageId, package_ecosystems: &[Ecosystem]) -> bool {
    if rule_id.name() != id.name() {
        return false;
    }
    match rule_id.ecosystem() {
        None => true,
        Some(eco) => package_ecosystems.contains(&eco),
    }
}

/// Two-pass `[[package]]` rule lookup with Prefixed-over-Bare specificity.
///
/// Pass 1: iterate `cfg.packages` in TOML-declaration order, return the
/// first entry where `rule_id.ecosystem().is_some()` AND
/// [`rule_applies`] -- prefixed rules (`cargo/`, `npm/`, `pypi/`) always beat
/// bare ones regardless of declaration order, but only among rules whose
/// ecosystem the package actually has.
///
/// Pass 2 (only if Pass 1 found nothing): same order, first entry where
/// [`rule_applies`].
///
/// `None` if neither pass matches.
///
/// MUST NOT sort or partition `cfg.packages` -- specificity comes solely
/// from two separate linear scans over the unmodified slice.
pub(crate) fn resolve_package_config<'a>(
    id: &PackageId,
    package_ecosystems: &[Ecosystem],
    cfg: &'a ResolvedConfig,
) -> Result<Option<&'a PackageConfig>, GraphError> {
    if let Some((_, pcfg)) = cfg
        .packages
        .iter()
        .find(|(rule_id, _)| rule_id.ecosystem().is_some() && rule_applies(rule_id, id, package_ecosystems))
    {
        return Ok(Some(pcfg));
    }
    if let Some((_, pcfg)) = cfg
        .packages
        .iter()
        .find(|(rule_id, _)| rule_applies(rule_id, id, package_ecosystems))
    {
        if let Some(siblings) = cfg.promoted_siblings.get(id.name()) {
            return Err(GraphError::AmbiguousName {
                name: id.name().to_string(),
                candidates: siblings.iter().map(|(pid, _)| pid.clone()).collect(),
            });
        }
        return Ok(Some(pcfg));
    }
    Ok(None)
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

/// Parses the five override fields shared by `[[package]]` and
/// `[[package-set]]` blocks (release-trigger, tag-template, changelog,
/// pre-major-inference, publish-to) into a `PackageConfig`.
///
/// `previous_tag_templates` is `[[package]]`-only; `[[package-set]]` callers pass `None`.
#[allow(clippy::too_many_arguments)]
fn parse_package_config_fields(
    callisto_toml: &Path,
                    key: format!(
                        "[registries.{}] publish-url (only a `pypi` registry has a separate upload route)",
                        key.as_str()
                    ),
                });
            }
            registries.insert(
                key,
                RegistryConfig {
                    kind,
                    url: reg.url,
                    publish_url: reg.publish_url,
                },
            );
        }
    }

    let raw_groups = RawGroupTable {
        fixed: raw.fixed_group.unwrap_or_default(),
        linked: raw.linked_group.unwrap_or_default(),
    };
    GroupTable::validate_syntactic(&raw_groups)?;

    if !raw_groups.fixed.is_empty() {
        provenance.insert(ConfigKey::FIXED_GROUP, ConfigProvenance::Explicit);
    }
    if !raw_groups.linked.is_empty() {
        provenance.insert(ConfigKey::LINKED_GROUP, ConfigProvenance::Explicit);
    }

    // Resolve [[package]] blocks into per-package override rules.
    // Order is preserved: first matching rule wins during package construction.
    let mut packages: Vec<(PackageId, PackageConfig)> = Vec::new();
    for raw_pkg in raw.package.unwrap_or_default() {
        let pattern = PackageId::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
            path: callisto_toml.clone(),
            key: format!("[[package]] match = {:?}: {e}", raw_pkg.pattern),
        })?;

        if raw_pkg.release_trigger.is_some() {
            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
        }
        if raw_pkg.tag_template.is_some() {
            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
        }
        if raw_pkg.pre_major_inference.is_some() {
            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
        }

        let cfg = parse_package_config_fields(
            &callisto_toml,
            "[[package]]",
            &raw_pkg.pattern,
            raw_pkg.release_trigger.as_deref(),
            raw_pkg.tag_template.as_deref(),
            raw_pkg.previous_tag_templates.as_deref(),
            raw_pkg.changelog.as_deref(),
            raw_pkg.pre_major_inference.as_deref(),
            raw_pkg.publish_to.as_deref(),
        )?;

        packages.push((pattern, cfg));
    }

    // Resolve [[package-set]] blocks into bulk config-override rules.
    // Semantics: each rule matches ALL packages whose PackageId matches the pattern.
    // A [[package]] rule takes priority; [[package-set]] is the fallback (see walk.rs).
    let mut package_sets: Vec<(PackagePattern, PackageConfig)> = Vec::new();
    for raw_pkg in raw.package_set.unwrap_or_default() {
        let pattern = PackagePattern::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
            path: callisto_toml.clone(),
            key: format!("[[package-set]] match = {:?}: {e}", raw_pkg.pattern),
        })?;

        if raw_pkg.release_trigger.is_some() {
            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
        }
        if raw_pkg.tag_template.is_some() {
            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
        }
        if raw_pkg.pre_major_inference.is_some() {
            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
        }

        let cfg = parse_package_config_fields(
            &callisto_toml,
            "[[package-set]]",
            &raw_pkg.pattern,
            raw_pkg.release_trigger.as_deref(),
            raw_pkg.tag_template.as_deref(),
            None,
            raw_pkg.changelog.as_deref(),
            raw_pkg.pre_major_inference.as_deref(),
            raw_pkg.publish_to.as_deref(),
        )?;

        package_sets.push((pattern, cfg));
    }

    Ok(ResolvedConfig {
        root: root.to_path_buf(),
        changesets_dir,
        cascade: CascadeConfig {
            mode,
            bump_severity,
            peer_escalation,
            preserve_npm_ranges,
        },
        validation: ValidationConfig { allow_empty_changesets },
        product_release,
        registries,
        packages,
        package_sets,
        groups: GroupTable::default(),
        raw_groups,
        promoted_siblings: BTreeMap::new(),
        provenance,
    })
}

