use serde::{Deserialize, Serialize};

use crate::{Diagnostic, Report};

/// Top-level report output from `callisto matrix --format json`.
///
/// `platform_targets`/`runtime_versions` are keyed by each package's
/// ecosystem-qualified identity (`PackageId::display_name()`: a bare name
/// when the package was never promoted, `ecosystem/name` once a same-name
/// package in another ecosystem forced promotion -- the common napi split
/// layout -- so a Cargo crate and an npm package sharing a bare name never
/// collide on one entry). BTreeMap guarantees lexicographic key ordering by
/// that id without a separate sort step.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct MatrixReport {
    pub schema_version: u32,
    pub platform_targets: BTreeMap<String, PlatformTargetGroup>,
    pub runtime_versions: BTreeMap<String, Vec<RuntimeVersionEntry>>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub diagnostics: Vec<Diagnostic>,
}

impl Report for MatrixReport {
    const COMMAND: &'static str = "matrix";

    fn schema_version(&self) -> u32 {
        self.schema_version
    }

    fn diagnostics(&self) -> &[Diagnostic] {
        &self.diagnostics
    }
}

/// One package's build target group: napi, maturin, or cargo `[[release.artifact]]`
/// binaries -- never more than one (see GraphError::ConflictingPlatformTargetSources).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct PlatformTargetGroup {
    pub kind: PlatformTargetKind,
    /// Raw manifest field name ("napi.targets", "[tool.maturin].targets", or
    /// "[[release.artifact]]"),
    /// used for audit output only -- not a filesystem path.
    pub source: String,
    /// Sorted ascending by triple string before serialization.
    pub targets: Vec<PlatformTarget>,
}

/// Deliberately omits a DotnetAot variant; out of scope for this spec.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum PlatformTargetKind {
    Napi,
    Maturin,
    /// A cargo binary configured as a `[[release.artifact]]`.
    Cargo,
}

impl fmt::Display for PlatformTargetKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            PlatformTargetKind::Napi => "napi",
            PlatformTargetKind::Maturin => "maturin",
            PlatformTargetKind::Cargo => "cargo",
        })
    }
}

/// One platform build target within a PlatformTargetGroup. No `rid` field
/// (napi/maturin only, no dotnet-aot).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct PlatformTarget {
    pub triple: String,
    pub platform: String,
    pub arch: String,
    pub abi: Option<String>,
    pub host_runner: String,
    pub use_cross: bool,
    /// For a cargo `[[release.artifact]]` entry, its configured asset name.
    pub artifact_name: String,
    /// Workspace-root-relative.
    pub package_dir: String,
    pub package_name: String,
    /// napi: the addon crate's workspace-relative `Cargo.toml` when it is not in `package_dir`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub manifest_path: Option<String>,
}

/// One package's runtime-version constraint, sourced from engines.node (npm)
/// or requires-python (python/PyPI). `range` is the raw, unvalidated manifest
/// string. No targetFrameworks field (dotnet-only, out of scope).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct RuntimeVersionEntry {
    pub ecosystem: RuntimeEcosystem,
    pub field: String,
    pub range: String,
}

/// Which manifest field a [`RuntimeVersionEntry`] was read from. Exactly two variants —
/// `callisto matrix` reads `engines.node` from `package.json` or `requires-python` from
/// `pyproject.toml` and nothing else; a third ecosystem (e.g. a future `.NET`
/// `TargetFramework` field) is deliberately out of scope, not merely unimplemented, so
/// deserializing an unrecognized ecosystem string is a schema error rather than silently
/// accepted.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum RuntimeEcosystem {
    Npm,
    Python,
}

impl fmt::Display for RuntimeEcosystem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            RuntimeEcosystem::Npm => "npm",
            RuntimeEcosystem::Python => "python",
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// An empty MatrixReport with no diagnostics
    /// serializes to exactly {"schemaVersion":1,"platformTargets":{},"runtimeVersions":{}}
    /// with no "diagnostics" key present.
    #[test]
    fn empty_matrix_report_serializes_with_no_diagnostics_key() {
        let report = MatrixReport {
            schema_version: 1,
            platform_targets: std::collections::BTreeMap::new(),
            runtime_versions: std::collections::BTreeMap::new(),
            diagnostics: Vec::new(),
        };
        let json = serde_json::to_value(&report).unwrap();
        assert_eq!(
            json,
            serde_json::json!({
                "schemaVersion": 1,
                "platformTargets": {},
                "runtimeVersions": {}
            })
        );
    }

    /// PlatformTargetKind has exactly two variants (napi, maturin) --
    /// deserializing a "dotnet-aot" kind must fail.
    #[test]
    fn platform_target_kind_rejects_unknown_dotnet_aot_variant() {
        let raw = serde_json::json!({
            "kind": "dotnet-aot",
            "source": "whatever",
            "targets": []
        });
        let result: Result<PlatformTargetGroup, _> = serde_json::from_value(raw);
        assert!(result.is_err(), "expected deserialization of kind=dotnet-aot to fail");
    }

    /// RuntimeEcosystem has exactly two variants (npm, python) --
    /// deserializing an "dotnet" ecosystem must fail.
    #[test]
    fn runtime_ecosystem_rejects_unknown_dotnet_variant() {
        let raw = serde_json::json!({
            "ecosystem": "dotnet",
            "field": "whatever",
            "range": "whatever"
        });
        let result: Result<RuntimeVersionEntry, _> = serde_json::from_value(raw);
        assert!(result.is_err(), "expected deserialization of ecosystem=dotnet to fail");
    }
}
use callisto_model::{CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, MatrixReport, PackageId};

use crate::error::GraphError;
use crate::matrix::{
    add_release_artifact_groups, build_matrix_report, MatrixPackageInput, NapiCrate, ReleaseArtifactInput,
};
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct MatrixOptions {
    /// When Some, restrict the report to exactly this one registered package.
    /// Accepts a bare name -- resolved only when it matches exactly one
    /// registered package (`GraphError::AmbiguousName` otherwise, listing
    /// the qualified candidates) -- or an ecosystem-qualified id
    /// (`cargo/foo`, `npm/foo`). Err(GraphError::UnknownPackage) when no
    /// registered package matches. Resolved through
    /// [`crate::IdentityIndex::resolve`], the one selector resolver shared
    /// with every other package-selecting surface.
    pub package: Option<String>,
    /// Resolve each napi package's addon crate into `manifestPath` (E204 when not exactly one).
    pub napi_crates: bool,
}

pub fn matrix<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    opts: &MatrixOptions,
) -> Result<MatrixReport, GraphError> {
    let all_packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();

    let selected = opts
        .package
        .as_deref()
        .map(|raw| resolve_selected_package(&all_packages, &ws.identity, raw))
        .transpose()?;

    let inputs: Vec<MatrixPackageInput> = all_packages
        .iter()
        .filter(|p| selected.as_ref().is_none_or(|id| p.id == *id))
        .map(|p| {
            let dir_rel = package_dir_rel(p);
            MatrixPackageInput {
                id: p.id.clone(),
                dir_abs: ws.root.join(&dir_rel),
                dir_rel,
                name: p.id.name().to_string(),
            }
        })
        .collect();

    let napi_crates = opts
        .napi_crates
        .then(|| workspace_napi_crates(ws, &all_packages))
        .transpose()?;
    let mut report = build_matrix_report(&inputs, napi_crates.as_deref())?;
    let mut artifacts = Vec::new();
    for artifact in ws
        .config
        .product_release
        .iter()
        .flat_map(|release| &release.artifacts)
        .filter(|artifact| artifact.package.ecosystem() == Some(callisto_model::Ecosystem::Cargo))
        .filter(|artifact| {
            selected
                .as_ref()
                .is_none_or(|id| ws.identity.identifies(&artifact.package, id))
        })
    {
        let resolved = all_packages.iter().find_map(|package| {
            let manifest = package
                .canonical_manifests()
                .find(|manifest| manifest.ecosystem() == callisto_model::Ecosystem::Cargo)?;
            ws.identity
                .identifies(&artifact.package, &package.id)
                .then_some((package, manifest))
        });
        let Some((package, manifest)) = resolved else {
            report.diagnostics.push(Diagnostic {
                code: DiagnosticCode::UnknownPackage,
                severity: DiagnosticSeverity::Warning,
                message: format!(
                    "`[[release.artifact]]` package `{}` (asset `{}`) is not a cargo package in this workspace; it has no matrix entry",
                    artifact.package, artifact.asset_name
                ),
                package: Some(artifact.package.clone()),
                path: None,
                escalated_by: None,
                governed_by: None,
            });
            continue;
        };
        artifacts.push(ReleaseArtifactInput {
            id: package.id.clone(),
            name: package.id.name().to_string(),
            dir_rel: manifest
                .path
                .parent()
                .map(|dir| dir.to_string_lossy().to_string())
                .unwrap_or_default(),
            target: artifact.target.clone(),
            asset_name: artifact.asset_name.clone(),
        });
    }
    add_release_artifact_groups(&mut report, &artifacts)?;
    Ok(report)
}

/// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
/// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
/// a bare name is accepted only when it names exactly one package.
fn resolve_selected_package(
    all_packages: &[&callisto_model::Package],
    identity: &crate::IdentityIndex,
    raw: &str,
) -> Result<PackageId, GraphError> {
    let resolved = identity.resolve(raw)?;
    if all_packages.iter().any(|p| p.id == resolved) {
        Ok(resolved)
    } else {
        Err(GraphError::UnknownPackage { id: resolved })
    }
}

/// Every workspace cargo package that builds a napi-rs addon.
fn workspace_napi_crates<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    packages: &[&callisto_model::Package],
) -> Result<Vec<NapiCrate>, GraphError> {
    let ctx = callisto_manifests::OpenContext::for_workspace_root(&ws.root)?;
    let mut crates = Vec::new();
    for decl in packages
        .iter()
        .flat_map(|package| package.canonical_manifests())
        .filter(|decl| decl.format == callisto_model::ManifestFormat::CargoToml)
    {
        if let Some(lib_name) = crate::manifest_cache::open_cached(&ws.manifest_cache, decl, &ctx)?.napi_lib_name() {
            crates.push(NapiCrate {
                lib_name,
                manifest_path: decl.path.to_string_lossy().into_owned(),
            });

